-- Generated by Claude Code — fälschlich als Person angelegte Ensembles und
-- Platzhalter-Personen dauerhaft bereinigen (täglich).
--
-- 20261020000002 lief nur einmal und nur für Namen, zu denen es schon ein
-- Ensemble gab. Jetzt:
--  1. Person = vorhandenes Ensemble (Name oder Alias) -> umhängen
--  2. Name endet auf Orchester/Chor/Ensemble/Quartett … (Wortende, nicht
--     Teilstring — "Matthias Schorn" ist kein Chor) -> Ensemble anlegen
--     und umhängen
--  3. Platzhalter ("NN", "N.N.", "tba", "Moderation") -> Mitwirkenden-
--     Einträge entfernen, Person löschen

create or replace function public.move_person_to_ensemble(p_person_id uuid, p_ensemble_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text;
begin
  select full_name into v_name from persons where id = p_person_id for update;
  if not found then return; end if;

    -- event_participants: erst Kollisionen wegräumen (unique index
    -- event_participants_event_ensemble_uniq greift sonst beim Umhängen),
    -- dann person_id durch ensemble_id ersetzen.
    delete from event_participants old
      where old.person_id = p_person_id and exists (
        select 1 from event_participants kept
        where kept.event_id = old.event_id and kept.ensemble_id = p_ensemble_id
      );
    update event_participants set person_id = null, ensemble_id = p_ensemble_id where person_id = p_person_id;

    -- Werke/Quellen/Kandidaten, die fälschlich auf die Person statt das
    -- Ensemble zeigen, gibt es für einen Chor praktisch nie (composer_id
    -- etc. sind personenspezifisch) — trotzdem sicherheitshalber leeren,
    -- damit keine verwaiste FK auf die gleich gelöschte Zeile stehen bleibt.
    update works set composer_id = null where composer_id = p_person_id;
    update sources set person_id = null where person_id = p_person_id;
    update entity_candidates set created_person_id = null where created_person_id = p_person_id;

    -- Bilder: Galerie-Bilder der Person werden Galerie-Bilder des Ensembles;
    -- ein bereits vorhandenes primäres Ensemble-Bild hat Vorrang.
    update images set is_primary = false
      where origin_type = 'person' and origin_id = p_person_id and is_primary
        and exists (select 1 from images where origin_type = 'ensemble' and origin_id = p_ensemble_id and is_primary);
    update images set origin_type = 'ensemble', origin_id = p_ensemble_id where origin_type = 'person' and origin_id = p_person_id;

    -- Provenienz-Einträge: nur übernehmen, wenn das Ensemble das Feld noch
    -- nicht hat, sonst verwaist die Zeile beim Löschen der Person.
    delete from field_provenance old where old.entity_type = 'person' and old.entity_id = p_person_id and exists (
      select 1 from field_provenance kept where kept.entity_type = 'ensemble' and kept.entity_id = p_ensemble_id and kept.field_name = old.field_name
    );
    update field_provenance set entity_type = 'ensemble', entity_id = p_ensemble_id where entity_type = 'person' and entity_id = p_person_id;

    -- Aliasse der fehlerhaften Person auf das Ensemble umhängen, Dubletten
    -- verwerfen; den alten Personennamen selbst als Alias sichern, falls er
    -- vom kanonischen Ensemble-Namen abweicht (z.B. Tippfehler-Varianten).
    delete from entity_aliases old where old.entity_type = 'person' and old.entity_id = p_person_id and (
      old.alias_normalized = public.normalize_entity_name((select name from ensembles where id = p_ensemble_id)) or exists (
        select 1 from entity_aliases kept where kept.entity_type = 'ensemble' and kept.entity_id = p_ensemble_id and kept.alias_normalized = old.alias_normalized
      )
    );
    update entity_aliases set entity_type = 'ensemble', entity_id = p_ensemble_id where entity_type = 'person' and entity_id = p_person_id;
    if public.normalize_entity_name(v_name) <> public.normalize_entity_name((select name from ensembles where id = p_ensemble_id)) then
      insert into entity_aliases (entity_type, entity_id, alias) values ('ensemble', p_ensemble_id, v_name) on conflict do nothing;
    end if;

    -- Favoriten/Interessen/Duplikat-Kandidaten/Audit-Flags für die Person
    -- kaskadieren automatisch (on delete cascade), es gibt keine
    -- Ensemble-Äquivalente, in die sie sinnvoll umgehängt werden könnten.
    delete from persons where id = p_person_id;
end;
$$;

create or replace function public.is_ensemble_like_name(p_name text)
returns boolean
language sql
immutable
as $$
  select lower(coalesce(p_name, '')) ~ '(orchester|chor|ensemble|quartett|quintett|sextett|oktett|philharmoniker|philharmonie|sinfonietta|consort|orchestra|choir|singers|bigband|kapelle)(\M|$)'
      or lower(coalesce(p_name, '')) ~ '\m(trio|duo|band)\M';
$$;

create or replace function public.cleanup_misfiled_persons()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  rec record;
  v_ensemble uuid;
  moved integer := 0;
  created integer := 0;
  placeholders integer := 0;
begin
  for rec in
    select p.id, p.full_name, coalesce(canon.id, alias.entity_id) as ensemble_id
    from persons p
    left join ensembles canon on public.normalize_entity_name(canon.name) = public.normalize_entity_name(p.full_name)
    left join entity_aliases alias on alias.entity_type = 'ensemble' and alias.alias_normalized = public.normalize_entity_name(p.full_name)
    where canon.id is not null or alias.entity_id is not null or public.is_ensemble_like_name(p.full_name)
  loop
    v_ensemble := rec.ensemble_id;
    if v_ensemble is null then
      insert into ensembles (name, type, slug)
      values (rec.full_name,
        (case
          when lower(rec.full_name) ~ '(chor|choir|singers)' then 'chor'
          when lower(rec.full_name) ~ '(orchester|orchestra|philharmon|sinfonietta|kapelle)' then 'orchester'
          when lower(rec.full_name) ~ '(bigband|band)' then 'big_band'
          when lower(rec.full_name) ~ '(quartett|quintett|sextett|oktett|trio|duo|consort|ensemble)' then 'kammerensemble'
          else 'sonstiges' end)::ensemble_type,
        trim(both '-' from regexp_replace(lower(public.person_name_key(rec.full_name)), '[^a-z0-9]+', '-', 'g')) || '-' || left(replace(gen_random_uuid()::text, '-', ''), 6))
      returning id into v_ensemble;
      created := created + 1;
    end if;
    begin
      perform public.move_person_to_ensemble(rec.id, v_ensemble);
      moved := moved + 1;
    exception when others then
      raise warning 'cleanup_misfiled_persons: % übersprungen: %', rec.full_name, sqlerrm;
    end;
  end loop;

  for rec in
    select id from persons
    where public.person_name_key(full_name) in ('nn', 'n n', 'tba', 'n a', 'moderation', 'unbekannt', 'diverse', 'verschiedene', 'kuenstler', 'kunstler')
  loop
    begin
      delete from event_participants where person_id = rec.id;
      update works set composer_id = null where composer_id = rec.id;
      delete from persons where id = rec.id;
      placeholders := placeholders + 1;
    exception when others then
      raise warning 'cleanup_misfiled_persons: Platzhalter % übersprungen: %', rec.id, sqlerrm;
    end;
  end loop;

  return jsonb_build_object('moved', moved, 'created_ensembles', created, 'placeholders_removed', placeholders);
end;
$$;

revoke all on function public.move_person_to_ensemble(uuid, uuid) from public, anon, authenticated;
revoke all on function public.cleanup_misfiled_persons() from public, anon, authenticated;

select cron.schedule('cleanup-misfiled-persons', '20 4 * * *', $$ select public.cleanup_misfiled_persons(); $$);
select public.cleanup_misfiled_persons();
